"""Simple independent 4J listening comparison; no further audio processing."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1]

def run():
    a=json.loads((HERE/'a-target-phase/report.json').read_text());b=json.loads((HERE/'b-sequence-continuity/report.json').read_text());h=json.loads((ROOT/'results/experiment-04h-phase-neighbors/report.json').read_text())
    ai=a['metrics'];bi=b['metrics'];hi=h['metrics']
    rows=[('Additional directly recognized cycles','—',str(ai['newly_recognized_cycles']),str(bi['newly_recognized_cycles'])),
          ('Inferred cycles','0',str(ai['inferred_cycles']),str(bi['inferred_cycles'])),
          ('Remaining unmodeled ambiguous cycles','119',str(ai['remaining_unmodeled_ambiguous_cycles']),str(bi['remaining_unmodeled_ambiguous_cycles'])),
          ('Time coverage',f"{hi['coverage_fraction']*100:.2f}%",f"{ai['coverage_fraction']*100:.2f}%",f"{bi['coverage_fraction']*100:.2f}%"),
          ('Significant flat gaps (4I definition)','102',str(ai['significant_gap_intervals']),str(bi['significant_gap_intervals'])),
          ('Contiguous modeled runs','268',str(ai['accepted_runs']),str(bi['accepted_runs'])),
          ('Residual / original energy',f"{hi['residual_energy_ratio']*100:.2f}%",f"{ai['residual_energy_ratio']*100:.2f}%",f"{bi['residual_energy_ratio']*100:.2f}%"),
          ('Modeled-frame error / modeled input',f"{hi['modeled_error_to_modeled_input_ratio']*100:.3f}%",f"{ai['modeled_error_ratio']*100:.3f}%",f"{bi['modeled_error_ratio']*100:.3f}%"),
          ('New-region error / new-region input','—',f"{ai['new_region_error_ratio']*100:.3f}%",f"{bi['new_region_error_ratio']*100:.3f}%"),
          ('Reconstruction RMSE',f"{hi['reconstruction_rmse']:.6f}",f"{ai['reconstruction_rmse']:.6f}",f"{bi['reconstruction_rmse']:.6f}"),
          ('Analysis time',f"{h['timings']['recognition_analysis_seconds']:.4f} s",f"{a['timings']['recognition_or_sequence_analysis_seconds']:.4f} s",f"{b['timings']['recognition_or_sequence_analysis_seconds']:.4f} s"),
          ('Total timed run before JSON',f"{h['timings']['total_run_before_json_seconds']:.3f} s",f"{a['timings']['total_before_json_seconds']:.3f} s",f"{b['timings']['total_before_json_seconds']:.3f} s"),
          ('Whole-process peak RSS',f"{h['peak_process_rss_bytes']/2**20:.2f} MiB",f"{a['peak_process_rss_bytes']/2**20:.2f} MiB",f"{b['peak_process_rss_bytes']/2**20:.2f} MiB")]
    table='<div class="scroll"><table><thead><tr><th>Measurement</th><th>4H baseline</th><th>4J-A</th><th>4J-B</th></tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    listening='<p><a href="../experiment-04h-phase-neighbors/reconstructed.wav">Frozen 4H reconstruction</a> · <a href="../experiment-04h-phase-neighbors/residual.wav">4H residual</a></p><label>Original reference<audio controls preload="none" src="a-target-phase/original_reference.wav"></audio></label>'
    for directory,title in [('a-target-phase','4J-A — phase-tolerant target recognition'),('b-sequence-continuity','4J-B — sequence-driven continuity')]:
        listening+=f'<section class="audio"><h3>{title}</h3><p><a href="{directory}/reconstructed.wav">Reconstructed WAV</a> · <a href="{directory}/residual.wav">Residual WAV</a> · <a href="{directory}/original_reference.wav">Original reference WAV</a></p><label>Reconstruction<audio controls preload="none" src="{directory}/reconstructed.wav"></audio></label><label>Residual<audio controls preload="none" src="{directory}/residual.wav"></audio></label></section>'
    timing='<table><thead><tr><th>Execution stage</th><th>A seconds</th><th>B seconds</th></tr></thead><tbody>'
    for key,label in [('setup_load_hash_seconds','Load and preservation hashes'),('recognition_or_sequence_analysis_seconds','Recognition / sequence proposals and verification'),('frozen_synthesis_seconds','Frozen 64-position synthesis'),('residual_and_exports_seconds','Residual and three exports'),('evaluation_and_preservation_seconds','Readback, evaluation, preservation checks')]:
        timing+=f'<tr><td>{label}</td><td>{a["timings"][key]:.4f}</td><td>{b["timings"][key]:.4f}</td></tr>'
    timing+='</tbody></table>'
    body=f'''<h1>Experiment 4J — two independent continuity tests</h1><p class="lead"><strong>A recovers 89 cycles through recognition. B independently infers 83 periods across 67 gaps.</strong> Neither branch uses the other’s additions. Both retain the frozen 4H 64-position sampler and original timing for already-recognized cycles.</p><h2>Listen</h2><p>Every file is full-length six-second stereo 44.1 kHz float32 WAV. No normalization, clipping, mastering, original-waveform fallback or autoplay. Reference files are exact copies of the frozen original conversion.</p>{listening}<h2>Measured comparison</h2>{table}
<p>“Remaining ambiguous” means original ambiguous cycles still not modeled to at least 95% of their frame support. In B, all original identity labels remain ambiguous even where a waveform has been inferred. Counts do not establish sound identities or overlapping-source separation.</p>
<h2>A: bounded target recognition</h2><p>Keep the historical best exemplar and the <strong>0.995</strong> threshold. Compare its shape at −0.5, −0.25, 0, +0.25 and +0.5 of a 64-position slot. All other 4H target, phase, harmonic, periodicity, family-relationship and neighbor gates remain unchanged. Comparison shifts are not applied to rendering. No cycle boundaries or discovery assignments are edited.</p><p>A recovers all <strong>57 isolated target-score failures</strong> highlighted by 4I, plus 32 other supported cycles. It does not infer missing periods or borrow B’s sequence logic. Phase shifting interpolates/smooths descriptors slightly, so a better score is not proof of a physical boundary error or common origin. Remaining weak or incompatible targets stay unexplained.</p>
<h2>B: short continuous phase/amplitude predictions</h2><p>Use only frozen 4H accepted cycles, without A’s added recognition. A proposal requires <strong>three stable context cycles on each side</strong>, coherent signed geometry, compatible separate family labels, ≤2% period variation, and flank amplitude ratio ≤1.2. A learned exemplar must dominate at least four of the six context occurrences. The missing span must close in <strong>one or two predicted periods</strong>, within 2% of the neighboring period scale. No leading/trailing extrapolation, long silence or unsupported transition is filled.</p><p>Predict the phase grid between observed anchors and interpolate neighboring amplitude/offset metadata. The missing waveform’s signature or scale is not copied. Feed these explicit inferred occurrences through the exact frozen 64-position renderer. Each gap receives only <strong>one fixed prediction</strong>: no phase/gain search against original and no minimization over alternative fills.</p><p>Before admission, compare that prediction with original audio: whole-gap error ≤5%, signed correlation ≥0.98, per-cycle error ≤8% and correlation ≥0.97, and no quiet block where the model predicts material. Quiet/endings, unrelated waveforms, inverted phase and unstable contexts are rejected in tests. Verification is not source separation; uncertainty remains attached to every inferred occurrence.</p><p>In this recording, 67 context-eligible proposals passed waveform verification: 51 single-period and 16 two-period continuations (83 inferred periods). Context-ineligible gaps remain untouched. No thresholds were tuned after observing the residual.</p>
<h2>Coherence and uncertainty</h2><p>B has slightly more residual energy than A but fewer modeled runs (201 versus 229), because it connects entire bounded gaps rather than adding only individual detected cycles. Some run breaks are tiny and may not be audible. B’s lower new-region error also reflects a different, more selectively supported set of intervals; it does not prove B is universally better. Of the newly modeled original ambiguous cycles, 76 overlap between branches, 13 are A-only and 7 are B-only. Those seven include five prior neighbor rejections and two prior periodicity-confidence rejections.</p><p>All original 4H accepted cycles and render-family choices remain. B uses new negative IDs and explicit <code>sequence-inferred, not directly recognized</code> provenance; identity labels are not merged. Unsupported material remains in residual. Inferred phases/amplitudes are predictions with recorded anchor IDs and verification metrics, not newly certified detections.</p><h2>Waveform and discontinuity checks</h2><p>New-region error is <strong>{100*ai['new_region_error_ratio']:.3f}% for A</strong> and <strong>{100*bi['new_region_error_ratio']:.3f}% for B</strong>. Worst new individual-period error is 2.331% in A and 1.605% in B. Maximum whole-waveform adjacent step remains 0.209021, identical to 4H. Maximum boundary step is 0.00563875 in A and 0.00563840 in B, versus 0.00563840 in baseline at the same evaluated boundaries. These statistics do not establish absence of audible clicks, gating or tonal artifacts.</p><p><strong>Please assess naturalness by listening.</strong> No new listening was performed. The 64-position upper-harmonic limitation remains unchanged. Reconstruction + residual matches original within <strong>7.45e-9</strong> per sample for both variants; this is export/subtraction conservation, not complete sound recovery.</p><h2>Actual execution cost</h2>{timing}<p>Each branch ran sequentially in a fresh process. Timings exclude development, process startup/imports, JSON writing, tests and page generation. Nine tests ran separately in 0.120 seconds. Whole-process RSS includes audit JSON, PCM and verification arrays, not just the new method’s working memory. Historical 4H figures are single-run context, not a controlled benchmark. No full-song throughput guarantee is implied.</p><h2>Tests, records and scope</h2><p>Nine tests passed: bounded target recovery, different-shape/polarity/large-phase rejection, unchanged confidence and relationship guards, neighbor-only inference, genuine silence/endings, unrelated or inverted missing material, duration/volume transitions, long gaps, two-period closure, independent exports and inference verification. Original reference samples match exactly; both WAV pairs pass float32 conservation.</p><p>All prior experiments and production files remain unchanged. No MIDI, fixed instrument identity, supplied scale, isolated stem, linear256, combined A+B reconstruction or 4K was used or started.</p><p><a href="README.md">Concise methods and reproduction</a> · <a href="a-target-phase/report.json">A measurements</a> · <a href="a-target-phase/decisions.json">A recognition evidence</a> · <a href="b-sequence-continuity/report.json">B measurements and inferred occurrence timing</a> · <a href="b-sequence-continuity/decisions.json">B proposals, context anchors and verification</a></p>'''
    css='''body{font:17px/1.5 system-ui,sans-serif;max-width:1050px;margin:28px auto;padding:0 18px;color:#1d2b39}h1{line-height:1.15}.lead{font-size:1.18rem}a{color:#125da8}h2{margin-top:32px}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:.92rem}th,td{text-align:left;padding:9px 10px;border-bottom:1px solid #c8d1db}th{background:#edf1f5}.audio{border-top:1px solid #c8d1db;margin:24px 0}audio{display:block;width:420px;max-width:100%;margin:8px 0 18px}code{font-family:ui-monospace,monospace}'''
    with (HERE/'listen.html').open('x') as f:f.write('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Independent Experiment 4J listening comparison</title><style>'+css+'</style></head><body>'+body+'</body></html>')

if __name__=='__main__':run()
